const { Sequelize, DataTypes, Op } = require('sequelize');

async function test() {
  const sequelize = new Sequelize({
    dialect: 'sqlite',
    storage: ':memory:',
    logging: console.log,
  });

  const User = sequelize.define('User', {
    username: {
      type: DataTypes.STRING,
      allowNull: false,
    },
  }, {
    paranoid: true,
  });

  const Post = sequelize.define('Post', {
    title: {
      type: DataTypes.STRING,
      allowNull: false,
    },
  }, {
    paranoid: true,
  });

  User.hasMany(Post, { foreignKey: 'userId' });
  Post.belongsTo(User, { foreignKey: 'userId' });

  // Hooks
  User.afterDestroy(async (user, options) => {
    console.log('afterDestroy hook called. User deletedAt:', user.deletedAt);
    await Post.destroy({
      where: { userId: user.id },
      transaction: options.transaction,
    });
  });

  User.beforeRestore(async (user, options) => {
    console.log('beforeRestore hook called. User deletedAt:', user.deletedAt);
    // Restore posts that were deleted at or after the user's deletion
    await Post.restore({
      where: {
        userId: user.id,
        deletedAt: {
          [Op.gte]: user.deletedAt,
        },
      },
      transaction: options.transaction,
    });
  });

  await sequelize.sync({ force: true });

  // 1. Create User and Posts
  const user = await User.create({ username: 'alice' });
  const post1 = await Post.create({ title: 'Post 1', userId: user.id });
  const post2 = await Post.create({ title: 'Post 2', userId: user.id });

  // 2. Soft-delete Post 1 manually
  console.log('\n--- Soft-deleting Post 1 manually ---');
  await post1.destroy();

  // Wait a bit to ensure timestamp difference
  await new Promise(resolve => setTimeout(resolve, 1000));

  // 3. Soft-delete User
  console.log('\n--- Soft-deleting User ---');
  await user.destroy();

  // Wait a bit
  await new Promise(resolve => setTimeout(resolve, 1000));

  // 4. Check status
  console.log('\n--- Checking status after User delete ---');
  const allPosts = await Post.findAll({ paranoid: false, where: { userId: user.id } });
  for (const p of allPosts) {
    console.log(`Post: ${p.title}, deletedAt: ${p.deletedAt}`);
  }

  // 5. Restore User
  console.log('\n--- Restoring User ---');
  await user.restore();

  // 6. Check status after restore
  console.log('\n--- Checking status after User restore ---');
  const activePosts = await Post.findAll({ where: { userId: user.id } });
  console.log('Active posts (should only be Post 2):');
  for (const p of activePosts) {
    console.log(`Post: ${p.title}, deletedAt: ${p.deletedAt}`);
  }

  const deletedPosts = await Post.findAll({ paranoid: false, where: { userId: user.id, deletedAt: { [Op.ne]: null } } });
  console.log('Deleted posts (should only be Post 1):');
  for (const p of deletedPosts) {
    console.log(`Post: ${p.title}, deletedAt: ${p.deletedAt}`);
  }

  await sequelize.close();
}

test().catch(console.error);

